// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(address newLog) public {
        // Initialization freezes configuration in the reference contract.
        c.Initialized();
        // In the reference C, SetLogFile reverts forever after initialization,
        // for ANY input. The mutant lets the log address be overwritten.
        bool ok;
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "SetLogFile must always revert after initialization");
    }
}
